"""
Generates the typing stubs which give IDEs autocomplete for mref.

Traits are bound at runtime, so an IDE cannot know which methods a
``ReferencedItem`` has. This module writes two stub files next to the
package:

``types.pyi``
    One ``<Name>Trait`` class per trait, holding that trait's public
    method signatures and docstrings, and one ``<NodeType>Node`` class
    per Maya node type, inheriting the traits which bind to that node
    type in the same priority order mref resolves them at runtime.

``__init__.pyi``
    The package's public API, with ``create`` overloaded per node type
    so ``mref.create("joint")`` is typed as ``mref.types.JointNode``.

Re-run :func:`generate_stubs` whenever a trait is added or a trait's
methods change. Working out which traits bind to which node type means
creating one node of every type, which can crash Maya for a handful of
internal types — so that part always runs in a separate ``mayapy``
process (restarted, skipping the offending type, if it does crash) and
never touches the calling session's scene.
"""
import ast
import inspect
import json
import os
import re
import subprocess
import sys
import tempfile

# -- Plugins loaded by the probe process in addition to any loaded in the
# -- calling session, so their node types get stubs too.
DEFAULT_PLUGINS = ("matrixNodes", "quatNodes", "lookdevKit", "mtoa")

# -- Node types known to crash Maya when created outside of the UI.
# -- Others are found (and skipped) automatically.
KNOWN_CRASHING_TYPES = ("caddyManipBase",)

# -- Restarts of the probe process allowed before giving up.
_MAX_PROBE_RUNS = 30

_HEADER = '''"""
Generated by mref.generate_stubs() - do not edit by hand.

Maya {maya_version}. Plugins loaded during generation: {plugins}.
Re-run mref.generate_stubs() after adding or changing traits.
"""
'''


def generate_stubs(probe: bool = True, plugins: list[str] = None, mayapy: str = None) -> list[str]:
    """
    Regenerates ``mref/types.pyi`` and ``mref/__init__.pyi`` from the
    traits currently on disk, followed by the HTML docs (see
    :func:`mref.documentation.generate_docs`), and returns the paths
    written.

    :param probe: If True (default), works out afresh which traits bind
        to every Maya node type, in a separate mayapy process (a minute or
        two). Pass False when you have only added or changed methods on
        existing traits — the node type to trait mapping is then reused
        from the existing ``types.pyi`` and generation takes about a
        second. A new trait, or a change to a ``can_bind``, needs a probe.
    :param plugins: Plugins whose node types should be included. Defaults
        to :data:`DEFAULT_PLUGINS` plus every plugin loaded in the current
        session. Only used when probing.
    :param mayapy: Path to the ``mayapy`` executable used for the probe
        process. Defaults to the one belonging to the running Maya.
    """
    import mref

    package_dir = os.path.dirname(mref.__file__)
    types_path = os.path.join(package_dir, "types.pyi")

    if probe:
        if plugins is None:
            plugins = sorted(set(DEFAULT_PLUGINS) | set(_loaded_plugins()))
        result = _run_probe(plugins, mayapy or _find_mayapy())
    else:
        result = read_stub_probe(types_path)

    header = _HEADER.format(
        maya_version=result["maya_version"],
        plugins=", ".join(result["plugins"]) or "none",
    )

    _write(types_path, header + render_types(result["node_types"]))

    init_path = os.path.join(package_dir, "__init__.pyi")
    _write(init_path, header + render_init(result["node_types"]))

    # -- The HTML docs are built from the same data, so keep them in step
    from . import documentation
    docs_path = documentation.generate_docs()

    return [types_path, init_path, docs_path]


# ------------------------------------------------------------------------------
# Rendering
# ------------------------------------------------------------------------------
def render_trait_stubs() -> str:
    """
    Returns the ``<Name>Trait`` stub classes for every trait in the trait
    library, built from the trait source files.
    """
    blocks = []
    for trait in _traits_by_name():
        class_node = _class_node(trait)
        blocks.append(_render_trait_class(trait.__name__, class_node))

    return "\n\n".join(blocks) + "\n"


def render_types(node_types: dict) -> str:
    """
    Returns the contents of ``types.pyi``. ``node_types`` maps each Maya
    node type to the names of the traits which bind to it, highest
    priority first.
    """
    lines = [
        "import mref",
        "from mref.core import ReferencedItem, ReferenceList",
    ]
    lines.extend(_trait_imports())
    lines.append("")
    lines.append("")
    lines.append("# -- Traits " + "-" * 66)
    lines.append(render_trait_stubs())
    lines.append("")
    lines.append("# -- Attributes " + "-" * 62)
    lines.append("class Attribute(AttributeTrait, ReferencedItem):")
    lines.append('    """An attribute (plug) on a node."""')
    lines.append("")
    lines.append("")
    lines.append("# -- Node types " + "-" * 62)

    for node_type, class_name in _node_class_names(node_types).items():
        bases = [f"{name}Trait" for name in node_types[node_type]] + ["ReferencedItem"]
        lines.append(f"class {class_name}({', '.join(bases)}):")
        lines.append(f'    """A ``{node_type}`` node."""')
        lines.append("")

    return "\n".join(lines).rstrip() + "\n"


def render_init(node_types: dict) -> str:
    """
    Returns the contents of ``__init__.pyi`` — the package's public names
    re-exported as they are at runtime, with ``create`` overloaded for
    every node type.
    """
    import mref

    lines = [
        "import typing",
        "from typing import Literal, overload",
        "from . import types as types",
    ]
    functions = []

    init_tree = ast.parse(_read(mref.__file__))
    init_functions = {
        node.name: node
        for node in init_tree.body
        if isinstance(node, ast.FunctionDef)
    }

    for name in sorted(public_init_names()):
        if name in ("create", "get", "types"):
            continue
        value = getattr(mref, name)

        if inspect.ismodule(value):
            if value.__name__.startswith("mref."):
                lines.append(f"from . import {name} as {name}")
            else:
                package, _, module = value.__name__.rpartition(".")
                if package:
                    lines.append(f"from {package} import {module} as {name}")
                else:
                    lines.append(f"import {module} as {name}")
            continue

        module_name = getattr(value, "__module__", None)
        if module_name and module_name != "mref":
            lines.append(f"from {module_name} import {name} as {name}")
            continue

        if name in init_functions:
            functions.append(_render_function(init_functions[name], indent=""))

    lines.append("from .core import ReferencedItem, ReferenceList")
    lines.append("")
    lines.append("")
    lines.extend(functions)
    lines.append("def __getattr__(name: str) -> typing.Any:")
    lines.append('    """Any other name resolves to an mref-wrapped maya.cmds command."""')
    lines.append("")
    lines.append("")

    # -- The node type behind a name is only known at runtime, so a single
    # -- item is typed as Any. That lets callers annotate the result:
    # --     shape: mref.types.MeshNode = mref.get("pCube1Shape")
    get_docstring = _render_docstring(inspect.getdoc(mref.get) or "", indent="    ")
    lines.append("@overload")
    lines.append("def get(identifier: list) -> ReferenceList: ...")
    lines.append("@overload")
    lines.append("def get(identifier: typing.Any) -> typing.Any:")
    lines.append(get_docstring)
    lines.append("")
    lines.append("")

    for node_type, class_name in _node_class_names(node_types).items():
        lines.append("@overload")
        lines.append(
            f"def create(node_type: Literal[{node_type!r}], unique: bool = ..., "
            f"*args: typing.Any, **kwargs: typing.Any) -> types.{class_name}: ..."
        )

    lines.append("@overload")
    lines.append(
        "def create(node_type: str, unique: bool = ..., *args: typing.Any, "
        "**kwargs: typing.Any) -> ReferencedItem | ReferenceList: ..."
    )

    return "\n".join(lines) + "\n"


def public_init_names() -> set[str]:
    """
    Returns the public names ``mref/__init__.py`` itself defines or
    imports. Submodules which only appear on the package because
    something imported them (``mref.tests``, ``mref.traits``) are not
    included, so the generated stub does not depend on what happens to
    be loaded.
    """
    import mref

    names = set()
    for node in ast.parse(_read(mref.__file__)).body:
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            names.update(alias.asname or alias.name.split(".")[0] for alias in node.names)
        elif isinstance(node, (ast.FunctionDef, ast.ClassDef)):
            names.add(node.name)
        elif isinstance(node, ast.Assign):
            names.update(target.id for target in node.targets if isinstance(target, ast.Name))

    return {name for name in names if not name.startswith("_")}


def read_stub_probe(types_path: str) -> dict:
    """
    Recovers the probe result (Maya version, plugins and the node type to
    trait mapping) from a previously generated ``types.pyi``.
    """
    if not os.path.exists(types_path):
        raise RuntimeError(f"{types_path} does not exist yet; generate with probe=True first")

    content = _read(types_path)
    header = re.search(r"Maya (.+?)\. Plugins loaded during generation: (.*?)\.\n", content)
    if not header:
        raise RuntimeError(f"{types_path} was not generated by mref.generate_stubs()")

    node_types = dict()
    for node in ast.parse(content).body:
        if not isinstance(node, ast.ClassDef) or not node.name.endswith("Node"):
            continue
        match = re.fullmatch(r"A ``(.+)`` node\.", ast.get_docstring(node) or "")
        if not match:
            continue
        node_types[match.group(1)] = [
            base.id[:-len("Trait")]
            for base in node.bases
            if isinstance(base, ast.Name) and base.id.endswith("Trait")
        ]

    plugins = header.group(2)
    return dict(
        maya_version=header.group(1),
        plugins=[] if plugins == "none" else plugins.split(", "),
        node_types=node_types,
    )


def node_class_name(node_type: str) -> str:
    """
    Returns the ``mref.types`` class name for a Maya node type, for
    example ``"mesh"`` gives ``"MeshNode"``.
    """
    name = re.sub(r"\W", "_", node_type)
    return name[0].upper() + name[1:] + "Node"


def _node_class_names(node_types: dict) -> dict:
    """
    Maps each node type to a unique class name, in sorted order.
    """
    results = dict()
    used = set()

    for node_type in sorted(node_types):
        class_name = node_class_name(node_type)
        while class_name in used:
            class_name += "_"
        used.add(class_name)
        results[node_type] = class_name

    return results


def _render_trait_class(trait_name: str, class_node: ast.ClassDef) -> str:
    """
    Renders the stub class for one trait from its class definition.
    """
    lines = [f"class {trait_name}Trait:"]

    docstring = ast.get_docstring(class_node)
    if docstring:
        lines.append(_render_docstring(docstring, indent="    "))

    methods = [
        node for node in class_node.body
        if isinstance(node, ast.FunctionDef)
        and not node.name.startswith("_")
        and node.name not in ("can_bind", "dynamic_function")
    ]

    for method in methods:
        lines.append(_render_function(method, indent="    "))

    # -- A trait-level __getattr__ (DependencyNode's) resolves Maya
    # -- attribute names, so property-style access gives an attribute
    if any(isinstance(node, ast.FunctionDef) and node.name == "__getattr__" for node in class_node.body):
        lines.append("    def __getattr__(self, name: str) -> Attribute:")
        lines.append('        """Resolves a Maya attribute on this node, e.g. ``node.translateX``."""')

    if not docstring and not methods:
        lines.append("    ...")

    return "\n".join(lines)


def _render_function(node: ast.FunctionDef, indent: str) -> str:
    """
    Renders a function or method as a stub — its signature (with every
    default replaced by ``...``) and its docstring.
    """
    arguments = node.args
    stub_arguments = ast.arguments(
        posonlyargs=arguments.posonlyargs,
        args=arguments.args,
        vararg=arguments.vararg,
        kwonlyargs=arguments.kwonlyargs,
        kw_defaults=[
            None if default is None else ast.Constant(value=...)
            for default in arguments.kw_defaults
        ],
        kwarg=arguments.kwarg,
        defaults=[ast.Constant(value=...) for _ in arguments.defaults],
    )

    decorators = [
        f"{indent}@{ast.unparse(decorator)}"
        for decorator in node.decorator_list
        if ast.unparse(decorator) in ("staticmethod", "classmethod", "property")
    ]

    signature = f"{indent}def {node.name}({ast.unparse(stub_arguments)})"
    if node.returns is not None:
        signature += f" -> {ast.unparse(node.returns)}"

    docstring = ast.get_docstring(node)
    if docstring:
        body = _render_docstring(docstring, indent=indent + "    ")
        return "\n".join(decorators + [signature + ":", body])

    return "\n".join(decorators + [signature + ": ..."])


def _render_docstring(docstring: str, indent: str) -> str:
    docstring = docstring.replace("\\", "\\\\").replace('"""', '\\"\\"\\"')
    lines = docstring.splitlines()
    body = "\n".join(f"{indent}{line}" if line else "" for line in lines)
    return f'{indent}"""\n{body}\n{indent}"""'


def _trait_imports() -> list[str]:
    """
    Returns the import statements used across the trait modules, so that
    the annotations copied from them resolve in the stub.
    """
    imports = []
    for trait in _traits_by_name():
        tree = ast.parse(_read(inspect.getsourcefile(trait)))
        for node in tree.body:
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                statement = ast.unparse(node)
                if statement not in imports and statement != "import mref":
                    imports.append(statement)
    return imports


def _traits_by_name() -> list:
    import mref
    return sorted(mref.TraitLibrary.singleton().plugins(), key=lambda trait: trait.__name__)


def _class_node(trait) -> ast.ClassDef:
    tree = ast.parse(_read(inspect.getsourcefile(trait)))
    for node in tree.body:
        if isinstance(node, ast.ClassDef) and node.name == trait.__name__:
            return node
    raise RuntimeError(f"Could not find the definition of {trait.__name__}")


# ------------------------------------------------------------------------------
# Probing (runs in a separate mayapy process)
# ------------------------------------------------------------------------------
def _run_probe(plugins: list[str], mayapy: str) -> dict:
    """
    Runs :func:`_probe` in a separate mayapy process and returns its
    result. If the process crashes, the node type it was creating is
    skipped and the process is restarted.
    """
    working_dir = tempfile.mkdtemp(prefix="mref_stubs_")
    result_path = os.path.join(working_dir, "result.json")
    progress_path = os.path.join(working_dir, "progress.txt")
    skip_path = os.path.join(working_dir, "skip.txt")
    _write(skip_path, "\n".join(KNOWN_CRASHING_TYPES))

    environment = dict(os.environ)
    environment["PYTHONPATH"] = os.pathsep.join(
        _import_roots() + [environment.get("PYTHONPATH", "")]
    )
    environment["MAYA_SKIP_USERSETUP_PY"] = "1"

    # -- Run via -c rather than executing this file, which would put the
    # -- package folder first on sys.path and let mref/types.py shadow the
    # -- standard library types module
    command = [
        mayapy,
        "-c",
        "import sys; from mref import stubs; stubs._probe(*sys.argv[1:4], plugins=sys.argv[4].split(','))",
        result_path, progress_path, skip_path, ",".join(plugins),
    ]

    output = ""
    for _ in range(_MAX_PROBE_RUNS):
        completed = subprocess.run(
            command,
            env=environment,
            cwd=working_dir,
            capture_output=True,
            text=True,
            errors="replace",
        )
        output = completed.stdout + completed.stderr

        if completed.returncode == 0 and os.path.exists(result_path):
            with open(result_path) as handle:
                return json.load(handle)

        # -- The last type the probe started on is the one that crashed it
        progress = _read(progress_path).split() if os.path.exists(progress_path) else []
        if not progress:
            break

        print(f"mref: creating a {progress[-1]} node crashed the stub probe; skipping it and restarting")
        with open(skip_path, "a") as handle:
            handle.write("\n" + progress[-1])

    raise RuntimeError(f"mref stub probe failed:\n{output[-3000:]}")


def _probe(result_path: str, progress_path: str, skip_path: str, plugins: list[str]) -> None:
    """
    Creates one node of every type Maya knows about, records which traits
    bind to it, and undoes the creation. Writes the result as JSON.
    """
    import maya.standalone
    maya.standalone.initialize(name="python")

    from maya import cmds
    from maya.api import OpenMaya as om
    import mref

    loaded = []
    for plugin in filter(None, plugins):
        try:
            cmds.loadPlugin(plugin, quiet=True)
            loaded.append(plugin)
        except RuntimeError:
            pass

    skip = set(_read(skip_path).split())

    # -- Resolution order: highest priority first, as ReferencedItem does.
    # -- Traits sharing a priority are discovered in no fixed order (and
    # -- never share method names), so sort those by name to keep the
    # -- generated stubs stable between runs.
    traits = sorted(
        mref.TraitLibrary.singleton().plugins(),
        key=lambda trait: (-trait.priority, trait.__name__),
    )
    node_types = dict()

    with open(progress_path, "w") as progress:
        for node_type in cmds.allNodeTypes():
            if node_type in skip:
                continue

            progress.write(node_type + "\n")
            progress.flush()

            try:
                inherited = cmds.nodeType(node_type, isTypeName=True, inherited=True) or []
            except Exception:
                continue
            is_dag = "dagNode" in inherited
            modifier = om.MDagModifier() if is_dag else om.MDGModifier()

            # -- Abstract types refuse creation with a variety of errors
            try:
                node = modifier.createNode(node_type)
                modifier.doIt()
            except Exception:
                continue

            try:
                node = _created_node(node, node_type, is_dag)
                if node is not None:
                    node_types[node_type] = [
                        trait.__name__
                        for trait in traits
                        if _safe_can_bind(trait, node)
                    ]
            finally:
                modifier.undoIt()

    with open(result_path, "w") as handle:
        json.dump(
            dict(
                maya_version=cmds.about(version=True),
                plugins=loaded,
                node_types=node_types,
            ),
            handle,
        )


def _safe_can_bind(trait, node) -> bool:
    """
    Calls a trait's can_bind, treating any error as "does not bind" so a
    single misbehaving trait cannot abort the whole probe.
    """
    try:
        return bool(trait.can_bind(node))
    except Exception:
        return False


def _created_node(node, node_type: str, is_dag: bool):
    """
    Returns the node of the requested type from a modifier's createNode
    result. For shape types a DAG modifier returns the parent transform
    it created, so the shape is found among its children.
    """
    from maya.api import OpenMaya as om

    if om.MFnDependencyNode(node).typeName == node_type:
        return node

    if is_dag:
        dag_node = om.MFnDagNode(node)
        for index in range(dag_node.childCount()):
            child = dag_node.child(index)
            if om.MFnDependencyNode(child).typeName == node_type:
                return child

    return None


# ------------------------------------------------------------------------------
# Helpers
# ------------------------------------------------------------------------------
def _find_mayapy() -> str:
    """
    Returns the path to the mayapy belonging to the running Maya.
    """
    location = os.environ.get("MAYA_LOCATION")
    if not location:
        raise RuntimeError("MAYA_LOCATION is not set; pass the mayapy path explicitly")

    executable = "mayapy.exe" if sys.platform == "win32" else "mayapy"
    path = os.path.join(location, "bin", executable)
    if not os.path.exists(path):
        raise RuntimeError(f"Could not find mayapy at {path}")
    return path


def _import_roots() -> list[str]:
    """
    Returns the directories the probe process needs on its path to import
    mref and its dependencies the same way this process does.
    """
    roots = []
    for module_name in ("mref", "factories", "signalling"):
        module = sys.modules.get(module_name)
        if module is None or not getattr(module, "__file__", None):
            continue
        root = os.path.dirname(os.path.dirname(module.__file__))
        if root not in roots:
            roots.append(root)
    return roots


def _loaded_plugins() -> list[str]:
    try:
        from maya import cmds
        return cmds.pluginInfo(query=True, listPlugins=True) or []
    except Exception:
        return []


def _read(path: str) -> str:
    with open(path, encoding="utf-8") as handle:
        return handle.read()


def _write(path: str, content: str) -> None:
    with open(path, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(content)
